def fcs(data, start=0, end=-1):
    """CRC-16/X.25 of data[start:end] (end=-1 means len(data))."""
    if end < 0:
        end = len(data)
    table = _FCS_TABLE
    crc = 0xFFFF
    for i in range(start, end):
        crc = (crc >> 8) ^ table[(crc ^ data[i]) & 0xFF]
    return crc ^ 0xFFFF


def _is_call_char(c):
    return 48 <= c <= 57 or 65 <= c <= 90  # 0-9 A-Z


class Address:
    """One AX.25 address: callsign (str, up to 6 chars), SSID (0-15), H bit."""

    __slots__ = ("call", "ssid", "h")

    def __init__(self, call, ssid=0, h=False):
        self.call = call
        self.ssid = ssid
        self.h = h

    @staticmethod
    def parse(text):
        """'JA1XYZ-9' / 'WIDE2-1*' -> Address. Raises ValueError if not a valid AX.25 address."""
        h = text.endswith("*")
        if h:
            text = text[:-1]
        call, _, ssid = text.partition("-")
        call = call.upper()
        if not 1 <= len(call) <= 6:
            raise ValueError("bad callsign length: %r" % text)
        for c in call.encode():
            if not _is_call_char(c):
                raise ValueError("bad callsign char: %r" % text)
        n = 0
        if ssid:
            if not (ssid.isdigit() and len(ssid) <= 2):
                raise ValueError("bad SSID: %r" % text)
            n = int(ssid)
            if n > 15:
                raise ValueError("SSID out of range: %r" % text)
        return Address(call, n, h)

    @staticmethod
    def decode(buf, off):
        """Decode the 7 bytes at buf[off:off+7]. Returns (Address, is_last)."""
        chars = bytearray(6)
        n = 0
        for i in range(6):
            c = buf[off + i]
            if c & 0x01:
                raise DecodeError("address extension bit inside callsign")
            c >>= 1
            if c == 0x20:  # space padding
                break
            if not _is_call_char(c):
                raise DecodeError("bad callsign char 0x%02x" % c)
            chars[n] = c
            n += 1
        if n == 0:
            raise DecodeError("empty callsign")
        b = buf[off + 6]
        return Address(bytes(chars[:n]).decode(), (b >> 1) & 0x0F, bool(b & 0x80)), bool(b & 0x01)

    def encode_into(self, buf, off, last=False, cr=False):
        """Write 7 bytes into buf at off.
        cr sets bit 7 (command/response for dst/src, H bit for digipeaters)."""
        call = self.call.encode()
        for i in range(6):
            buf[off + i] = (call[i] if i < len(call) else 0x20) << 1
        b = 0x60 | ((self.ssid & 0x0F) << 1)
        if cr:
            b |= 0x80
        if last:
            b |= 0x01
        buf[off + 6] = b

    def __str__(self):
        s = self.call if self.ssid == 0 else "%s-%d" % (self.call, self.ssid)
        return s + "*" if self.h else s

    def __eq__(self, other):
        return (
            isinstance(other, Address)
            and self.call == other.call
            and self.ssid == other.ssid
            and self.h == other.h
        )


class Frame:
    """AX.25 UI frame. info is bytes (the APRS payload)."""

    __slots__ = ("dst", "src", "digis", "info")

    def __init__(self, dst, src, digis=None, info=b""):
        self.dst = dst
        self.src = src
        self.digis = digis if digis is not None else []
        self.info = info

    @staticmethod
    def decode(buf, n=-1):
        """Decode buf[:n] = frame bytes between the flags, including the 2-byte FCS.
        Raises DecodeError on bad FCS, malformed addresses or a non-UI frame."""
        if n < 0:
            n = len(buf)
        if n < _MIN_FRAME:
            raise DecodeError("frame too short (%d)" % n)
        rx = buf[n - 2] | (buf[n - 1] << 8)
        if fcs(buf, 0, n - 2) != rx:
            raise DecodeError("FCS mismatch")
        dst, last = Address.decode(buf, 0)
        if last:
            raise DecodeError("no source address")
        src, last = Address.decode(buf, ADDR_LEN)
        dst.h = src.h = False  # bit 7 is C/R here, not H
        digis = []
        off = ADDR_LEN * 2
        while not last:
            if len(digis) == MAX_DIGIS or off + ADDR_LEN > n - 4:
                raise DecodeError("address field not terminated")
            d, last = Address.decode(buf, off)
            digis.append(d)
            off += ADDR_LEN
        if buf[off] != CONTROL_UI or buf[off + 1] != PID_NO_L3:
            raise DecodeError("not a UI frame (ctl=0x%02x pid=0x%02x)" % (buf[off], buf[off + 1]))
        return Frame(dst, src, digis, bytes(buf[off + 2 : n - 2]))

    def encode(self):
        """-> bytearray of the frame between the flags, including FCS."""
        if len(self.digis) > MAX_DIGIS:
            raise ValueError("too many digipeaters")
        na = 2 + len(self.digis)
        n = na * ADDR_LEN + 2 + len(self.info)
        buf = bytearray(n + 2)
        # command frame: C bit set on dst, clear on src (AX.25 v2.x)
        self.dst.encode_into(buf, 0, cr=True)
        self.src.encode_into(buf, ADDR_LEN, last=not self.digis)
        off = ADDR_LEN * 2
        for i, d in enumerate(self.digis):
            d.encode_into(buf, off, last=i == len(self.digis) - 1, cr=d.h)
            off += ADDR_LEN
        buf[off] = CONTROL_UI
        buf[off + 1] = PID_NO_L3
        buf[off + 2 : n] = self.info
        c = fcs(buf, 0, n)
        buf[n] = c & 0xFF
        buf[n + 1] = c >> 8
        return buf

    @staticmethod
    def parse(text):
        """TNC2 monitor format 'SRC>DST,DIGI1,DIGI2*:info' -> Frame (info as bytes)."""
        if isinstance(text, (bytes, bytearray)):
            head, sep, info = bytes(text).partition(b":")
            head = head.decode()
        else:
            head, sep, s = text.partition(":")
            info = s.encode()
        if not sep:
            raise ValueError("no ':' in TNC2 text")
        src, sep, rest = head.partition(">")
        if not sep:
            raise ValueError("no '>' in TNC2 text")
        path = rest.split(",")
        return Frame(
            Address.parse(path[0]), Address.parse(src), [Address.parse(p) for p in path[1:]], info
        )

    def header(self):
        """'SRC>DST,DIGI1,DIGI2*' (only the last repeated digi gets the '*', like TNC2)."""
        last_h = -1
        for i, d in enumerate(self.digis):
            if d.h:
                last_h = i
        parts = [str(self.src), ">", str(self.dst)]
        for i, d in enumerate(self.digis):
            parts.append(",")
            parts.append(d.call if d.ssid == 0 else "%s-%d" % (d.call, d.ssid))
            if i == last_h:
                parts.append("*")
        return "".join(parts)
